/* ------------------------------------------------------------------ */
/* 15. load/store multiple                                             */
/* ------------------------------------------------------------------ */
static void test_ldm_stm(void)
{
	begin("stm");
	reset();
	cpu.r[0] = 0x8000u;
	cpu.r[1] = 0x11u;
	cpu.r[2] = 0x22u;
	set_flags(1, 1, 1, 1);
	eqi("rc", n2a32_t16(&cpu, E_STM), N2A32_OK);
	eq32("m0", mem32(0x8000u), 0x11u);
	eq32("m1", mem32(0x8004u), 0x22u);
	eq32("r0", cpu.r[0], 0x8008u);
	expect_flags(1, 1, 1, 1);
	end();

	begin("ldm");
	reset();
	cpu.r[0] = 0x8000u;
	put32(0x8000u, 0xAAu);
	put32(0x8004u, 0xBBu);
	set_flags(0, 1, 0, 1);
	eqi("rc", n2a32_t16(&cpu, E_LDM), N2A32_OK);
	eq32("r1", cpu.r[1], 0xAAu);
	eq32("r2", cpu.r[2], 0xBBu);
	eq32("r0", cpu.r[0], 0x8008u);
	expect_flags(0, 1, 0, 1);
	end();

	begin("stm2");
	reset();
	cpu.r[3] = 0x8000u;
	cpu.r[0] = 0x55u;
	cpu.r[7] = 0x77u;
	eqi("rc", n2a32_t16(&cpu, E_STM2), N2A32_OK);
	eq32("m0", mem32(0x8000u), 0x55u);
	eq32("m1", mem32(0x8004u), 0x77u);
	eq32("r3", cpu.r[3], 0x8008u);
	end();

	begin("ldm2");
	reset();
	cpu.r[5] = 0x8000u;
	put32(0x8000u, 1);
	put32(0x8004u, 2);
	put32(0x8008u, 3);
	put32(0x800Cu, 4);
	eqi("rc", n2a32_t16(&cpu, E_LDM2), N2A32_OK);
	eq32("r0", cpu.r[0], 1);
	eq32("r1", cpu.r[1], 2);
	eq32("r2", cpu.r[2], 3);
	eq32("r3", cpu.r[3], 4);
	eq32("r5", cpu.r[5], 0x8010u);
	end();

	begin("stm3");
	reset();
	cpu.r[7] = 0x8000u;
	cpu.r[0] = 0;
	cpu.r[1] = 1;
	cpu.r[2] = 2;
	cpu.r[3] = 3;
	cpu.r[4] = 4;
	cpu.r[5] = 5;
	cpu.r[6] = 6;
	eqi("rc", n2a32_t16(&cpu, E_STM3), N2A32_OK);
	eq32("m0", mem32(0x8000u), 0);
	eq32("m6", mem32(0x8018u), 6);
	eq32("r7", cpu.r[7], 0x801Cu);
	end();
}

