	expect_flags(1, 0, 1, 0);
	end();

	begin("bkpt0_state");
	reset();
	cpu.r[7] = 0x1234u;
	eqi("rc", n2a32_t16(&cpu, E_BKPT0), N2A32_UNDEF);
	eq32("r7", cpu.r[7], 0x1234u);
	eqi("stop", cpu.stop, N2A32_STOP_BKPT);
	end();

	/* SVC: six cases */
	begin("svc_flags");
	reset();
	set_flags(1, 1, 1, 1);
	eqi("rc", n2a32_t16(&cpu, E_SVC), N2A32_UNDEF);
	eqi("stop", cpu.stop, N2A32_STOP_SVC);
