	eqi("rc", n2a32_t16(&cpu, E_SVC), N2A32_UNDEF);
	eq32("r0", cpu.r[0], 0xAAAAu);
	eq32("next_pc", cpu.next_pc, NEXTPC);
	end();

	begin("svc_it");
	reset();
	cpu.in_it = 1;
	eqi("rc", n2a32_t16(&cpu, E_SVC), N2A32_UNDEF);
	eqi("stop", cpu.stop, N2A32_STOP_SVC);
	end();

	begin("svc_insn");
